import itertools
P=df['P'].values; y=df['dP_dt'].values; t=df['t'].values
L=np.log(P)
Pf={'1':1+0*P,'P':P,'P2':P**2,'P3':P**3,'L':L,'PL':P*L,'P2L':P**2*L,'iP':1/P,'P3L':P**3*L,'iPL':L/P,'sqP':np.sqrt(P),'isqP':P**-0.5,'expP':np.exp(-P),'L2':L**2,'P4':P**4,'PL2':P*L**2}
names=list(Pf)
vy=np.var(y)
def err(fs,tp):
    cols=[Pf[f]*t**k for f in fs for k in tp]
    X=np.column_stack(cols)
    c=np.linalg.lstsq(X,y,rcond=None)[0]
    return np.mean((y-X@c)**2)/vy
for tp in [(0,1,2,3),(0,1,2)]:
    found=[]
    for k in range(2,6):
        for fs in itertools.combinations(names,k):
            e=err(fs,tp)
            if e<1e-9: found.append((k,fs,e))
        if found: break
    print(tp, found[:10])

